from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/core/middleware.py', 'from __future__ import annotations\n\nimport logging\nimport time\nimport uuid\nfrom collections import defaultdict, deque\nfrom collections.abc import Awaitable, Callable\nfrom threading import Lock\n\nfrom fastapi import Request, Response\nfrom starlette.middleware.base import BaseHTTPMiddleware\nfrom starlette.responses import JSONResponse\n\nfrom app.core.config import get_settings\n\nlogger = logging.getLogger("http")\n\n\nclass RequestContextMiddleware(BaseHTTPMiddleware):\n    async def dispatch(\n        self,\n        request: Request,\n        call_next: Callable[[Request], Awaitable[Response]],\n    ) -> Response:\n        request_id = request.headers.get("X-Request-ID") or str(uuid.uuid4())\n        request.state.request_id = request_id\n        started = time.perf_counter()\n        try:\n            response = await call_next(request)\n        except Exception:\n            logger.exception(\n                "Unhandled request error",\n                extra={"request_id": request_id, "path": request.url.path, "method": request.method},\n            )\n            raise\n        duration_ms = round((time.perf_counter() - started) * 1000, 2)\n        response.headers["X-Request-ID"] = request_id\n        response.headers["X-Content-Type-Options"] = "nosniff"\n        response.headers["X-Frame-Options"] = "DENY"\n        response.headers["Referrer-Policy"] = "no-referrer"\n        logger.info(\n            "request",\n            extra={\n                "request_id": request_id,\n                "path": request.url.path,\n                "method": request.method,\n                "status_code": response.status_code,\n                "duration_ms": duration_ms,\n            },\n        )\n        return response\n\n\nclass SimpleRateLimitMiddleware(BaseHTTPMiddleware):\n    def __init__(self, app):\n        super().__init__(app)\n        self._events: dict[str, deque[float]] = defaultdict(deque)\n        self._lock = Lock()\n\n    async def dispatch(\n        self,\n        request: Request,\n        call_next: Callable[[Request], Awaitable[Response]],\n    ) -> Response:\n        settings = get_settings()\n        if request.url.path in {"/health", "/ready", "/metrics"}:\n            return await call_next(request)\n        identity = request.headers.get("X-API-Key") or (\n            request.client.host if request.client else "unknown"\n        )\n        now = time.monotonic()\n        cutoff = now - settings.rate_limit_window_seconds\n        with self._lock:\n            queue = self._events[identity]\n            while queue and queue[0] < cutoff:\n                queue.popleft()\n            if len(queue) >= settings.rate_limit_requests:\n                return JSONResponse(\n                    status_code=429,\n                    content={\n                        "detail": {\n                            "code": "RATE_LIMITED",\n                            "message": "Request rate limit exceeded.",\n                        }\n                    },\n                    headers={"Retry-After": str(settings.rate_limit_window_seconds)},\n                )\n            queue.append(now)\n        return await call_next(request)\n')
write('app/db/__init__.py', '')
write('app/db/base.py', 'from __future__ import annotations\n\nfrom sqlalchemy.orm import DeclarativeBase\n\n\nclass Base(DeclarativeBase):\n    pass\n')
